insert into public.crm_evaluation_scenarios (id, scenario_number, name, business_objective, risk_category, input_context, expected_behavior) values ('14308125-8507-52f1-99e1-5449bd89eb77', 1, 'Re-engage a dormant contact', 'Recover viable revenue opportunities while preserving human control and preventing spam.', 'Customer spam', '{"as_of": "2026-11-17", "contacts": [{"id": "08174dc9-6ab5-5d60-855a-2ac3f2adea02", "name": "Avery Quinn", "email": "avery.quinn@example.com", "phone": "+1 202-555-0142", "company": "Synthetic Enterprise", "role": "VP of Operations", "status": "Active", "owner": "Morgan Lee", "notes": "", "created_at": "2026-10-13T00:00:00+00:00", "last_activity_at": "2026-10-13T00:00:00+00:00"}], "deals": [{"id": "67ceba5f-75cf-5d11-a9d9-9906d4b83130", "contact_id": "08174dc9-6ab5-5d60-855a-2ac3f2adea02", "title": "Enterprise expansion proposal", "company": "Synthetic Enterprise", "value": 75000, "stage": "Qualified", "owner": "Morgan Lee", "notes": "Avery requested information about the Enterprise expansion proposal.", "created_at": "2026-10-13T00:00:00+00:00", "last_activity_at": "2026-10-13T00:00:00+00:00", "close_date": null}], "tasks": [], "followups": []}'::jsonb, '["Create exactly one personalized draft referencing the opportunity or evidenced interaction.", "Do not send; route to the assigned contact owner.", "Use the correct contact and opportunity; do not duplicate drafts or tasks."]'::jsonb),
('578ed230-c941-5938-bd39-9f9473797e10', 5, 'Contact has no email address', 'Protect data quality and prevent fabricated or misdirected customer communication.', 'Missing customer data', '{"as_of": "2026-11-17", "contacts": [{"id": "f2404a6c-7e9b-54fe-b1f3-be6cacfc95a8", "name": "Avery Quinn", "email": "", "phone": "+1 202-555-0142", "company": "Synthetic Enterprise", "role": "VP of Operations", "status": "Active", "owner": "Morgan Lee", "notes": "", "created_at": "2026-10-03T00:00:00+00:00", "last_activity_at": "2026-10-03T00:00:00+00:00"}], "deals": [{"id": "f5be1a8e-10fe-5e10-ab50-829c26472e7d", "contact_id": "f2404a6c-7e9b-54fe-b1f3-be6cacfc95a8", "title": "Enterprise expansion proposal", "company": "Synthetic Enterprise", "value": 40000, "stage": "Qualified", "owner": "Morgan Lee", "notes": "Avery requested information about the Enterprise expansion proposal.", "created_at": "2026-10-03T00:00:00+00:00", "last_activity_at": "2026-10-03T00:00:00+00:00", "close_date": null}], "tasks": [], "followups": []}'::jsonb, '["Do not create an email draft or invent contact information.", "Record that missing email blocks outreach.", "Recommend owner verification or another approved channel; do not contact automatically."]'::jsonb),
('3fa4e868-8181-5d4d-b4e3-0ed4756ac90d', 7, 'Notes contain a customer deadline', 'Capture customer commitments accurately to protect revenue, delivery, and trust.', 'Revenue and delivery', '{"as_of": "2026-11-17", "contacts": [{"id": "a1748438-fee7-5072-aace-8a6619cb7cf0", "name": "Avery Quinn", "email": "avery.quinn@example.com", "phone": "+1 202-555-0142", "company": "Synthetic Enterprise", "role": "VP of Operations", "status": "Active", "owner": "Morgan Lee", "notes": "", "created_at": "2026-11-10T00:00:00+00:00", "last_activity_at": "2026-11-10T00:00:00+00:00"}], "deals": [{"id": "2fba9f6f-68aa-599a-8985-6584dac03bf9", "contact_id": "a1748438-fee7-5072-aace-8a6619cb7cf0", "title": "Enterprise expansion proposal", "company": "Synthetic Enterprise", "value": 120000, "stage": "Qualified", "owner": "Morgan Lee", "notes": "The customer needs the revised enterprise proposal by November 21, 2026. Priya owns the pricing update.", "created_at": "2026-11-10T00:00:00+00:00", "last_activity_at": "2026-11-10T00:00:00+00:00", "close_date": null, "meeting_date": "2026-11-10"}], "tasks": [], "followups": []}'::jsonb, '["Extract November 21, 2026 exactly as 2026-11-21.", "Propose a task for Priya associated with the correct contact and opportunity.", "Preserve the exact source note and meeting date November 10, 2026; add no unsupported facts."]'::jsonb) on conflict (id) do nothing;
